//! Deterministic offline building-node insertion baseline. Not the final ALNS engine.
use serde::{Serialize,Deserialize};
#[derive(Clone,Serialize,Deserialize)] pub struct Point {pub lat:f64,pub lon:f64}
#[derive(Clone,Serialize,Deserialize)] pub struct Node {pub id:String,pub lat:f64,pub lon:f64,pub service_min:f64,#[serde(default)]pub members:Vec<String>,#[serde(default)]pub pinned_route:Option<usize>}
#[derive(Clone,Serialize,Deserialize)] pub struct Fleet {pub n:usize}
#[derive(Clone,Serialize,Deserialize)] pub struct Input {pub depot:Point,pub target_min:f64,pub hard_max_min:f64,pub fleet:Fleet,pub nodes:Vec<Node>}
#[derive(Clone,Serialize,Deserialize)] pub struct Route {pub number:usize,pub node_ids_in_order:Vec<String>,pub duration_min:f64,pub drive_min:f64,pub service_min:f64,pub miles:f64}
#[derive(Serialize,Deserialize)] pub struct Output {pub routes:Vec<Route>,pub unserved:Vec<String>,pub feasible:bool,pub longest:f64,pub spread:f64}
fn miles(a:&Point,b:&Point)->f64 {let rad=std::f64::consts::PI/180.;let h=((b.lat-a.lat)*rad/2.).sin().powi(2)+(a.lat*rad).cos()*(b.lat*rad).cos()*((b.lon-a.lon)*rad/2.).sin().powi(2);3958.8*2.*h.sqrt().atan2((1.-h).max(0.).sqrt())*1.35}
fn score(ids:&[usize],input:&Input)->(f64,f64,f64){if ids.is_empty(){return (0.,0.,0.)}let mut prev=input.depot.clone();let(mut dist,mut service)=(0.,0.);for i in ids {let n=&input.nodes[*i];let p=Point{lat:n.lat,lon:n.lon};dist+=miles(&prev,&p);service+=n.service_min;prev=p;}dist+=miles(&prev,&input.depot);let drive=dist/18.*60.+(ids.len()+1)as f64*1.5;(drive,service,dist)}
pub fn solve(input:&Input)->Result<Output,String>{if input.fleet.n==0||input.fleet.n>150{return Err("Fleet must contain 1–150 teams".into())}if input.nodes.len()>3000{return Err("Maximum 3,000 building nodes".into())}if !input.hard_max_min.is_finite()||input.hard_max_min<=0.{return Err("Invalid duration limit".into())}let mut seen=std::collections::HashSet::new();for n in &input.nodes{if !seen.insert(&n.id)||!n.lat.is_finite()||!n.lon.is_finite()||n.lat.abs()>90.||n.lon.abs()>180.||!n.service_min.is_finite()||n.service_min<0.{return Err("Invalid or duplicate node".into())}}
let mut buckets=vec![Vec::<usize>::new();input.fleet.n];let mut order=(0..input.nodes.len()).collect::<Vec<_>>();order.sort_by(|a,b|{let x=&input.nodes[*a];let y=&input.nodes[*b];(x.lat-input.depot.lat).atan2(x.lon-input.depot.lon).total_cmp(&(y.lat-input.depot.lat).atan2(y.lon-input.depot.lon))});let mut unserved=vec![];for i in order{let mut best:Option<(usize,usize,f64)>=None;for (r,ids) in buckets.iter().enumerate(){if input.nodes[i].pinned_route.is_some_and(|p|p!=r+1){continue}let old=score(ids,input);for pos in 0..=ids.len(){let mut trial=ids.clone();trial.insert(pos,i);let(d,s,_)=score(&trial,input);let total=d+s;if total>input.hard_max_min{continue}let cost=total*2.+(d-old.0)*3.+(total-input.target_min).max(0.).powi(2);if best.is_none()||cost<best.unwrap().2{best=Some((r,pos,cost))}}}if let Some((r,pos,_))=best{buckets[r].insert(pos,i)}else{unserved.push(input.nodes[i].id.clone())}}
let routes=buckets.iter().enumerate().filter(|(_,ids)|!ids.is_empty()).map(|(r,ids)|{let(d,s,m)=score(ids,input);Route{number:r+1,node_ids_in_order:ids.iter().map(|i|input.nodes[*i].id.clone()).collect(),duration_min:d+s,drive_min:d,service_min:s,miles:m}}).collect::<Vec<_>>();let longest=routes.iter().map(|r|r.duration_min).fold(0.,f64::max);let shortest=routes.iter().map(|r|r.duration_min).reduce(f64::min).unwrap_or(0.);Ok(Output{routes,feasible:unserved.is_empty(),unserved,longest,spread:longest-shortest})}
#[cfg(test)]mod tests{use super::*;fn fixture()->Input{Input{depot:Point{lat:34.1478,lon:-118.1445},target_min:195.,hard_max_min:225.,fleet:Fleet{n:45},nodes:(0..750).map(|i|Node{id:i.to_string(),lat:34.14+(i%25)as f64*0.001,lon:-118.14+(i/25)as f64*0.001,service_min:9.,members:vec![i.to_string()],pinned_route:None}).collect()}}#[test]fn all_served_once_within_limit(){let input=fixture();let out=solve(&input).unwrap();assert!(out.feasible);let ids=out.routes.iter().flat_map(|r|r.node_ids_in_order.iter()).collect::<std::collections::HashSet<_>>();assert_eq!(ids.len(),750);assert!(out.routes.iter().all(|r|r.duration_min<=225.));assert!(out.spread<=45.);assert_eq!(serde_json::to_string(&out).unwrap(),serde_json::to_string(&solve(&input).unwrap()).unwrap())}#[test]fn infeasibility_is_explicit(){let mut i=fixture();i.fleet.n=1;assert!(!solve(&i).unwrap().feasible)}#[test]fn pinned_route(){let mut i=fixture();i.nodes[0].pinned_route=Some(4);let o=solve(&i).unwrap();assert!(o.routes.iter().find(|r|r.number==4).unwrap().node_ids_in_order.contains(&"0".into()))}}
